	JAE   finish
	MOVQ  strs+16(FP), R8
	CMPB  ptrs+32(FP), $0x00
	JEQ   value
	MOVQ  (R8)(CX*8), R8
	TESTQ R8, R8
	JNZ   header

	// nil: the null string.
	MOVQ 16(SP), DI
	LEAQ 1(DI), AX
	CMPQ AX, 24(SP)
	JA   finish
	MOVB $0x00, (DI)
	MOVQ AX, 16(SP)
	INCQ R14
	JMP  next

value:
	SHLQ $0x04, CX
	ADDQ CX, R8

header:
	MOVQ  (R8), SI
	MOVQ  8(R8), BX
	MOVQ  16(SP), DI
	TESTQ BX, BX
	JNZ   text
	LEAQ  1(DI), AX
	CMPQ  AX, 24(SP)
	JA    finish
	MOVB  $0x01, (DI)
	MOVQ  AX, 16(SP)
	INCQ  R14
	JMP   next

text:
	CMPQ      BX, $const_wireMaxText
	JAE       finish
	LEAQ      const_wireSlack+1(DI)(BX*2), AX
	CMPQ      AX, 24(SP)
	JA        finish
	CMPQ      BX, $0x20
	JAE       long
	LEAQ      -1(SI), R8
	MOVL      R8, R9
	ANDL      $0x00000fff, R9
	CMPL      R9, $0x00000fe0
	JA        long
	LEAQ      wire<>+672(SB), R10
	ADDQ      $0x1f, R10
	SUBQ      BX, R10
	VMOVDQU   (R8), Y0
	VPAND     (R10), Y0, Y0
	VPAND     wire<>+736(SB), Y0, Y0
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       long

	// The header, 2n+1, in the first byte.
	LEAL    1(BX)(BX*1), CX
	VMOVD   CX, X1
	VPOR    Y1, Y0, Y0
	VMOVDQU Y0, (DI)

	// Stored with its header.
	LEAQ 1(DI)(BX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

long:
	INCQ  DI
	MOVQ  DI, 8(SP)
	MOVQ  DI, (SP)
	XORQ  DX, DX
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12

latin1:
	MOVQ    BX, AX
	SUBQ    DX, AX
	JLE     latin1Done
	MOVL    $0xffffffff, R13
	CMPQ    AX, $0x20
	JB      ltail
	VMOVDQU (SI)(DX*1), Y0
	JMP     lbody

ltail:
	// Fewer than 32 bytes left: R13 the mask of those, the bytes past them zeros.
	MOVL    $0x00000001, R13
	MOVQ    AX, CX
	SHLL    CL, R13
	DECL    R13
	LEAQ    (SI)(DX*1), R8
	MOVL    R8, R9
	ANDL    $0x00000fff, R9
	CMPL    R9, $0x00000fe0
	JA      lcopy
	VMOVDQU (R8), Y0
	LEAQ    wire<>+672(SB), R10
	ADDQ    $0x20, R10
	SUBQ    AX, R10
	VPAND   (R10), Y0, Y0
	JMP     lbody

lcopy:
	// The 32 bytes from there cross into the next page: the bytes left are copied to where the output goes
	// next (room not written yet), then read from there.
	VPXOR   Y0, Y0, Y0
	VMOVDQU Y0, (DI)
	XORQ    R9, R9

lbyte:
	MOVBLZX (R8)(R9*1), R10
	MOVB    R10, (DI)(R9*1)
	INCQ    R9
	CMPQ    R9, AX
	JB      lbyte
	VMOVDQU (DI), Y0

lbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       lchars

	// ASCII: no char of the block before may be cut.
	VPSUBUSB wire<>+544(SB), Y14, Y4
	VPOR     Y4, Y12, Y12
	VMOVDQU  Y0, (DI)
	POPCNTL  R13, R8
	ADDQ     R8, DI
	VMOVDQA  Y0, Y14
	ADDQ     $0x20, DX
	JMP      latin1

lchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	VPSUBUSB wire<>+160(SB), Y0, Y4
	VPTEST   Y4, Y4
