	VPALIGNR     $0x0f, Y1, Y0, Y2
	VPAND        wire<>+224(SB), Y0, Y7
	VPCMPEQB     wire<>+256(SB), Y7, Y4
	VPCMPEQB     Y13, Y7, Y7
	VPOR         Y7, Y12, Y12
	VPAND        wire<>+224(SB), Y2, Y5
	VPCMPEQB     wire<>+256(SB), Y5, Y5
	VPCMPGTB     Y0, Y13, Y6
	VPXOR        Y6, Y5, Y5
	VPOR         Y5, Y12, Y12
	VPCMPEQB     wire<>+160(SB), Y2, Y5
	VPAND        wire<>+192(SB), Y5, Y5
	VPADDB       Y5, Y0, Y6
	VPMOVMSKB    Y4, R8
	NOTL         R8
	ANDL         R13, R8
	MOVL         R8, R9
	ANDL         $0x000000ff, R9
	MOVL         R8, R10
	SHRL         $0x08, R10
	ANDL         $0x000000ff, R10
	MOVL         R8, R11
	SHRL         $0x10, R11
	ANDL         $0x000000ff, R11
	MOVL         R8, R12
	SHRL         $0x18, R12
	LEAQ         ·narrowLo+0(SB), AX
	LEAQ         ·narrowHi+0(SB), CX
	VMOVQ        (AX)(R9*8), X4
	VPINSRQ      $0x01, (CX)(R10*8), X4, X4
	VMOVQ        (AX)(R11*8), X7
	VPINSRQ      $0x01, (CX)(R12*8), X7, X7
	VINSERTI128  $0x01, X7, Y4, Y4
	VPSHUFB      Y4, Y6, Y6
	POPCNTL      R9, R9
	POPCNTL      R10, R10
	POPCNTL      R11, R11
	POPCNTL      R12, R12
	VMOVDQU      X6, (DI)
	VPEXTRQ      $0x01, X6, CX
	MOVQ         CX, (DI)(R9*1)
	ADDQ         R9, DI
	ADDQ         R10, DI
	VEXTRACTI128 $0x01, Y6, X7
	VMOVDQU      X7, (DI)
	VPEXTRQ      $0x01, X7, CX
	MOVQ         CX, (DI)(R11*1)
	ADDQ         R11, DI
	ADDQ         R12, DI
	VMOVDQA      Y0, Y14
	ADDQ         $0x20, DX
	JMP          latin1

latin1Done:
	VPSUBUSB wire<>+544(SB), Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
