wchars:
	// Check the block (Keiser and Lemire): Y1 the byte three before each, Y2 one before, Y3 two before.
	VPERM2I128     $0x21, Y0, Y14, Y1
	VPALIGNR       $0x0f, Y1, Y0, Y2
	VPALIGNR       $0x0e, Y1, Y0, Y3
	VPALIGNR       $0x0d, Y1, Y0, Y1
	VBROADCASTI128 wire<>+576(SB), Y8
	VBROADCASTI128 wire<>+608(SB), Y9
	VBROADCASTI128 wire<>+640(SB), Y10
	VPSRLW         $0x04, Y2, Y4
	VPAND          Y11, Y4, Y4
	VPSHUFB        Y4, Y8, Y4
	VPAND          Y11, Y2, Y5
	VPSHUFB        Y5, Y9, Y5
	VPSRLW         $0x04, Y0, Y6
	VPAND          Y11, Y6, Y6
	VPSHUFB        Y6, Y10, Y6
	VPAND          Y5, Y4, Y4
	VPAND          Y6, Y4, Y4
	VPSUBUSB       wire<>+64(SB), Y3, Y5
	VPSUBUSB       wire<>+96(SB), Y1, Y6
	VPOR           Y6, Y5, Y5
	VPAND          wire<>+128(SB), Y5, Y5
	VPXOR          Y5, Y4, Y4
	VPOR           Y4, Y12, Y12
	VMOVDQA        Y0, Y14
	VPCMPGTB       Y0, Y13, Y4
	VPCMPGTB       Y2, Y13, Y5
