	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND     wire<>+384(SB), Y2, Y6
	VPSLLW    $0x02, Y6, Y6
	VPSRLW    $0x04, Y0, Y7
	VPAND     wire<>+448(SB), Y7, Y7
	VPOR      Y7, Y6, Y6
	VPSUBB    wire<>+192(SB), Y6, Y7
	VPBLENDVB Y9, Y7, Y4, Y4
	VPAND     Y13, Y6, Y6
	VPCMPEQB  Y15, Y6, Y6
	VPAND     wire<>+416(SB), Y3, Y7
	VPADDB    wire<>+480(SB), Y7, Y7
	VPADDB    Y6, Y7, Y7
	VPBLENDVB Y9, Y7, Y8, Y8

	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND     wire<>+448(SB), Y5, Y7
	VPOR      wire<>+512(SB), Y7, Y7
	VPBLENDVB Y10, Y7, Y8, Y8

wpack:
	VPUNPCKLBW   Y8, Y4, Y5
	VPUNPCKHBW   Y8, Y4, Y6
	MOVL         R8, R9
	ANDL         $0x000000ff, R9
	MOVL         R8, R10
	SHRL         $0x08, R10
	ANDL         $0x000000ff, R10
	MOVL         R8, R11
	SHRL         $0x10, R11
	ANDL         $0x000000ff, R11
	MOVL         R8, R12
	SHRL         $0x18, R12
