	MOVL         R9, CX
	SHLL         $0x04, CX
	VMOVDQU      (AX)(CX*1), X7
	MOVL         R11, CX
	SHLL         $0x04, CX
	VINSERTI128  $0x01, (AX)(CX*1), Y7, Y7
	VPSHUFB      Y7, Y5, Y5
	MOVL         R10, CX
	SHLL         $0x04, CX
	VMOVDQU      (AX)(CX*1), X7
	MOVL         R12, CX
	SHLL         $0x04, CX
	VINSERTI128  $0x01, (AX)(CX*1), Y7, Y7
	VPSHUFB      Y7, Y6, Y6
	POPCNTL      R9, R9
	POPCNTL      R10, R10
	POPCNTL      R11, R11
	POPCNTL      R12, R12
	VMOVDQU      X5, (DI)
	LEAQ         (DI)(R9*2), DI
	VMOVDQU      X6, (DI)
	LEAQ         (DI)(R10*2), DI
	VEXTRACTI128 $0x01, Y5, X7
	VMOVDQU      X7, (DI)
	LEAQ         (DI)(R11*2), DI
	VEXTRACTI128 $0x01, Y6, X7
	VMOVDQU      X7, (DI)
	LEAQ         (DI)(R12*2), DI
	ADDQ         $0x20, DX
	JMP          wide

wideDone:
	VPSUBUSB wire<>+544(SB), Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      invalid
	MOVQ     DI, AX
	SUBQ     (SP), AX
