	// Latin-1: the header 2n+1.
	LEAL 1(AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

store16:
	// UTF-16: the header 2n.
	NOTQ AX
	LEAL (AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*2), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

finish:
	MOVQ R14, done+40(FP)
	MOVQ 16(SP), AX
	SUBQ dst+0(FP), AX
	MOVQ AX, written+48(FP)
	VZEROUPPER
	RET

// func wireStringAVX512(dst unsafe.Pointer, i int, src unsafe.Pointer, n int) int
// Requires: AVX, AVX2, AVX512BW, AVX512F, AVX512VBMI2, AVX512VL, POPCNT
TEXT ·wireStringAVX512(SB), NOSPLIT, $16-40
	MOVQ            src+16(FP), SI
	MOVQ            i+8(FP), DX
	ADDQ            DX, SI
	MOVQ            n+24(FP), BX
	SUBQ            DX, BX
	MOVQ            dst+0(FP), DI
	LEAQ            (DI)(DX*2), AX
	MOVQ            AX, (SP)
	ADDQ            DX, DI
	MOVQ            DI, 8(SP)
	VPXOR           Y15, Y15, Y15
	VMOVDQU         wire<>+32(SB), Y11
	VMOVDQU         wire<>+0(SB), Y13
	VBROADCASTI32X4 wire<>+576(SB), Y16
	VBROADCASTI32X4 wire<>+608(SB), Y17
	VBROADCASTI32X4 wire<>+640(SB), Y18
	XORQ            DX, DX
	VPXOR           Y14, Y14, Y14
	VPXOR           Y12, Y12, Y12
	XORL            R12, R12

