	KMOVD       K3, R10
	KMOVD       K2, R11
	MOVL        R12, AX
	ANDL        $0x01, AX
	LEAQ        (AX)(R10*2), AX
	XORL        R9, AX
	JNZ         invalid
	MOVL        R10, AX
	ORL         R9, AX
	NOTL        AX
	ANDL        R8, AX
	JNZ         invalid
	MOVL        R12, CX
	SHRL        $0x01, CX
	LEAQ        (CX)(R11*2), CX
	KMOVD       CX, K4
	MOVL        R10, R12
	SHRL        $0x1f, R12
	SHRL        $0x1f, R11
	LEAL        (R12)(R11*2), R12
	VMOVDQA     Y0, Y6
	VPADDB      wire<>+192(SB), Y0, K4, Y6
