latin1Done:
	TESTL R12, R12
	JNZ   invalid
	MOVQ  DI, AX
	SUBQ  8(SP), AX
	JMP   done

toUTF16:
	// From the start again, as UTF-16: the block in Y0 when it is the first.
	MOVQ  (SP), DI
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
