	VPBLENDMB  Y5, Y8, K6, Y8
	VMOVDQU8.Z Y8, K7, Y8

	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VPAND    wire<>+352(SB), Y3, Y9
	VPCMPEQB wire<>+320(SB), Y9, K1
	VPAND    wire<>+352(SB), Y1, Y10
	VPCMPEQB wire<>+320(SB), Y10, K2
	KORTESTD K1, K2
	JZ       wpack

	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND     wire<>+384(SB), Y2, Y6
	VPSLLW    $0x02, Y6, Y6
	VPSRLW    $0x04, Y0, Y7
	VPAND     wire<>+448(SB), Y7, Y7
	VPOR      Y7, Y6, Y6
	VPSUBB    wire<>+192(SB), Y6, Y7
	VPBLENDMB Y7, Y4, K1, Y4
	VPAND     Y13, Y6, Y6
	VPCMPEQB  Y15, Y6, Y6
	VPAND     wire<>+416(SB), Y3, Y7
	VPADDB    wire<>+480(SB), Y7, Y7
	VPADDB    Y6, Y7, Y7
	VPBLENDMB Y7, Y8, K1, Y8

	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND     wire<>+448(SB), Y5, Y7
	VPOR      wire<>+512(SB), Y7, Y7
	VPBLENDMB Y7, Y8, K2, Y8

wpack:
	VPMOVZXBW   Y4, Z4
	VPMOVZXBW   Y8, Z5
	VPSLLW      $0x08, Z5, Z5
	VPORQ       Z5, Z4, Z4
	KMOVD       R8, K2
	VPCOMPRESSW Z4, K2, Z4
	VMOVDQU64   Z4, (DI)
	POPCNTL     R8, R8
	LEAQ        (DI)(R8*2), DI
	ADDQ        $0x20, DX
	JMP         wide

wideDone:
	VPSUBUSB wire<>+544(SB), Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      invalid
	MOVQ     DI, AX
	SUBQ     (SP), AX
	SHRQ     $0x01, AX
	NOTQ     AX
	JMP      done

invalid:
	MOVQ $0x7fffffffffffffff, AX

done:
	MOVQ AX, ret+32(FP)
	VZEROUPPER
	RET

// func wireStringsAVX512(dst unsafe.Pointer, room int, strs unsafe.Pointer, count int, ptrs bool) (done int, written int)
// Requires: AVX, AVX2, AVX512BW, AVX512F, AVX512VBMI2, AVX512VL, POPCNT
TEXT ·wireStringsAVX512(SB), NOSPLIT, $32-56
	MOVQ            dst+0(FP), AX
	MOVQ            AX, 16(SP)
	ADDQ            room+8(FP), AX
	MOVQ            AX, 24(SP)
	XORQ            R14, R14
	VPXOR           Y15, Y15, Y15
	VMOVDQU         wire<>+32(SB), Y11
	VMOVDQU         wire<>+0(SB), Y13
	VBROADCASTI32X4 wire<>+576(SB), Y16
	VBROADCASTI32X4 wire<>+608(SB), Y17
	VBROADCASTI32X4 wire<>+640(SB), Y18

next:
	MOVQ  R14, CX
	CMPQ  CX, count+24(FP)
	JAE   finish
	MOVQ  strs+16(FP), R8
	CMPB  ptrs+32(FP), $0x00
	JEQ   value
	MOVQ  (R8)(CX*8), R8
	TESTQ R8, R8
	JNZ   header

	// nil: the null string.
	MOVQ 16(SP), DI
	LEAQ 1(DI), AX
	CMPQ AX, 24(SP)
	JA   finish
	MOVB $0x00, (DI)
	MOVQ AX, 16(SP)
	INCQ R14
	JMP  next

value:
	SHLQ $0x04, CX
	ADDQ CX, R8

header:
	MOVQ  (R8), SI
	MOVQ  8(R8), BX
	MOVQ  16(SP), DI
	TESTQ BX, BX
	JNZ   text
	LEAQ  1(DI), AX
	CMPQ  AX, 24(SP)
	JA    finish
	MOVB  $0x01, (DI)
	MOVQ  AX, 16(SP)
	INCQ  R14
	JMP   next

text:
	CMPQ       BX, $const_wireMaxText
	JAE        finish
	LEAQ       const_wireSlack+1(DI)(BX*2), AX
	CMPQ       AX, 24(SP)
	JA         finish
	CMPQ       BX, $0x20
	JAE        long
	MOVQ       BX, CX
	MOVL       $0x00000002, R13
	SHLL       CL, R13
	SUBL       $0x02, R13
	KMOVD      R13, K1
	VMOVDQU8.Z -1(SI), K1, Y0
	VPMOVMSKB  Y0, R8
	TESTL      R8, R8
	JNZ        slatin

sstore:
	// The header, 2n+1, in the first byte.
	LEAL    1(BX)(BX*1), CX
	VMOVD   CX, X1
	VPOR    Y1, Y0, Y0
	VMOVDQU Y0, (DI)
	JMP     sdone

slatin:
	VPSUBUSB    wire<>+160(SB), Y0, Y4
	VPTEST      Y4, Y4
	JNZ         long
	VPCMPGTB    Y0, Y13, K1
	VPCMPEQB    wire<>+160(SB), Y0, K2
	VPAND       wire<>+224(SB), Y0, Y4
	VPCMPEQB    wire<>+256(SB), Y4, K3
	KMOVD       K1, R9
	KMOVD       K3, R10
	KMOVD       K2, R11
	MOVL        R10, AX
	ADDQ        AX, AX
	XORQ        R9, AX
	JNZ         long
	MOVL        R10, AX
	ORL         R9, AX
	NOTL        AX
	ANDL        R8, AX
	JNZ         long
	ADDL        R11, R11
	KMOVD       R11, K4
	VPADDB      wire<>+192(SB), Y0, K4, Y0
	POPCNTL     R10, AX
	SUBQ        AX, BX
	NOTL        R10
	KMOVD       R10, K2
	VPCOMPRESSB Y0, K2, Y0
	JMP         sstore

sdone:
	// Stored with its header.
	LEAQ 1(DI)(BX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

long:
	INCQ  DI
	MOVQ  DI, 8(SP)
	MOVQ  DI, (SP)
	XORQ  DX, DX
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
	XORL  R12, R12

latin1:
	MOVQ    BX, AX
	SUBQ    DX, AX
	JLE     latin1Done
	CMPQ    AX, $0x20
	JB      ltail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     lbody

ltail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL       $0x00000001, R13
	MOVQ       AX, CX
	SHLL       CL, R13
	DECL       R13
	KMOVD      R13, K1
	VMOVDQU8.Z (SI)(DX*1), K1, Y0

lbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       lchars

	// ASCII: no char of the block before may be cut.
	TESTL   R12, R12
	JNZ     invalid
	VMOVDQU Y0, (DI)
	POPCNTL R13, R8
	ADDQ    R8, DI
	ADDQ    $0x20, DX
	JMP     latin1

lchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	VPSUBUSB wire<>+160(SB), Y0, Y4
	VPTEST   Y4, Y4
	JNZ      toUTF16

	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly
	// the bytes after the leads, and there are no C0 or C1.
	VPCMPGTB    Y0, Y13, K1
	VPCMPEQB    wire<>+160(SB), Y0, K2
	VPAND       wire<>+224(SB), Y0, Y4
	VPCMPEQB    wire<>+256(SB), Y4, K3
	KMOVD       K1, R9
	KMOVD       K3, R10
	KMOVD       K2, R11
	MOVL        R12, AX
	ANDL        $0x01, AX
	LEAQ        (AX)(R10*2), AX
	XORL        R9, AX
	JNZ         invalid
	MOVL        R10, AX
	ORL         R9, AX
	NOTL        AX
	ANDL        R8, AX
	JNZ         invalid
	MOVL        R12, CX
	SHRL        $0x01, CX
	LEAQ        (CX)(R11*2), CX
	KMOVD       CX, K4
	MOVL        R10, R12
	SHRL        $0x1f, R12
	SHRL        $0x1f, R11
	LEAL        (R12)(R11*2), R12
	VMOVDQA     Y0, Y6
	VPADDB      wire<>+192(SB), Y0, K4, Y6
	NOTL        R10
	ANDL        R13, R10
	KMOVD       R10, K2
	VPCOMPRESSB Y6, K2, Y6
	VMOVDQU     Y6, (DI)
	POPCNTL     R10, R10
	ADDQ        R10, DI
	ADDQ        $0x20, DX
	JMP         latin1

latin1Done:
	TESTL R12, R12
	JNZ   invalid
	MOVQ  DI, AX
	SUBQ  8(SP), AX
	JMP   done

toUTF16:
	// From the start again, as UTF-16: the block in Y0 when it is the first.
	MOVQ  (SP), DI
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
	TESTQ DX, DX
	JZ    wchars
	XORQ  DX, DX

wide:
	MOVQ    BX, AX
	SUBQ    DX, AX
	JLE     wideDone
	CMPQ    AX, $0x20
	JB      wtail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     wbody

wtail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL       $0x00000001, R13
	MOVQ       AX, CX
	SHLL       CL, R13
	DECL       R13
	KMOVD      R13, K1
	VMOVDQU8.Z (SI)(DX*1), K1, Y0

wbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       wchars
	VPSUBUSB  wire<>+544(SB), Y14, Y4
	VPOR      Y4, Y12, Y12
	VPMOVZXBW Y0, Z4
	VMOVDQU64 Z4, (DI)
	POPCNTL   R13, R8
	LEAQ      (DI)(R8*2), DI
	VMOVDQA   Y0, Y14
	ADDQ      $0x20, DX
	JMP       wide

wchars:
	// Check the block (Keiser and Lemire): Y1 the byte three before each, Y2 one before, Y3 two before.
	VPERM2I128 $0x21, Y0, Y14, Y1
	VPALIGNR   $0x0f, Y1, Y0, Y2
	VPALIGNR   $0x0e, Y1, Y0, Y3
	VPALIGNR   $0x0d, Y1, Y0, Y1
	VPSRLW     $0x04, Y2, Y4
	VPAND      Y11, Y4, Y4
	VPSHUFB    Y4, Y16, Y4
	VPAND      Y11, Y2, Y5
	VPSHUFB    Y5, Y17, Y5
	VPSRLW     $0x04, Y0, Y6
	VPAND      Y11, Y6, Y6
	VPSHUFB    Y6, Y18, Y6
	VPAND      Y5, Y4, Y4
	VPAND      Y6, Y4, Y4
	VPSUBUSB   wire<>+64(SB), Y3, Y5
	VPSUBUSB   wire<>+96(SB), Y1, Y6
	VPOR       Y6, Y5, Y5
	VPAND      wire<>+128(SB), Y5, Y5
	VPXOR      Y5, Y4, Y4
	VPOR       Y4, Y12, Y12
	VMOVDQA    Y0, Y14
	VPCMPGTB   Y0, Y13, K3
	VPCMPGTB   Y2, Y13, K4
	VPAND      wire<>+288(SB), Y2, Y6
	VPCMPEQB   Y13, Y6, K6
	VPMOVB2M   Y0, K7
	KORD       K6, K4, K4
	KANDD      K3, K4, K4
	KNOTD      K7, K5
	KORD       K5, K4, K4
	KMOVD      K4, R8
	ANDL       R13, R8

	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VPAND     wire<>+384(SB), Y0, Y4
	VPSLLW    $0x06, Y2, Y5
	VPAND     Y13, Y5, Y5
	VPOR      Y5, Y4, Y4
	VPBLENDMB Y4, Y0, K7, Y4

	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VPSRLW     $0x02, Y2, Y5
	VPAND      Y11, Y5, Y5
	VPSLLW     $0x04, Y3, Y8
	VPAND      wire<>+320(SB), Y8, Y8
	VPOR       Y5, Y8, Y8
	VPBLENDMB  Y5, Y8, K6, Y8
	VMOVDQU8.Z Y8, K7, Y8

	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VPAND    wire<>+352(SB), Y3, Y9
	VPCMPEQB wire<>+320(SB), Y9, K1
	VPAND    wire<>+352(SB), Y1, Y10
	VPCMPEQB wire<>+320(SB), Y10, K2
	KORTESTD K1, K2
	JZ       wpack

	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND     wire<>+384(SB), Y2, Y6
	VPSLLW    $0x02, Y6, Y6
	VPSRLW    $0x04, Y0, Y7
	VPAND     wire<>+448(SB), Y7, Y7
	VPOR      Y7, Y6, Y6
	VPSUBB    wire<>+192(SB), Y6, Y7
	VPBLENDMB Y7, Y4, K1, Y4
	VPAND     Y13, Y6, Y6
	VPCMPEQB  Y15, Y6, Y6
	VPAND     wire<>+416(SB), Y3, Y7
	VPADDB    wire<>+480(SB), Y7, Y7
	VPADDB    Y6, Y7, Y7
	VPBLENDMB Y7, Y8, K1, Y8

	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND     wire<>+448(SB), Y5, Y7
	VPOR      wire<>+512(SB), Y7, Y7
	VPBLENDMB Y7, Y8, K2, Y8

wpack:
	VPMOVZXBW   Y4, Z4
	VPMOVZXBW   Y8, Z5
	VPSLLW      $0x08, Z5, Z5
	VPORQ       Z5, Z4, Z4
	KMOVD       R8, K2
	VPCOMPRESSW Z4, K2, Z4
	VMOVDQU64   Z4, (DI)
	POPCNTL     R8, R8
	LEAQ        (DI)(R8*2), DI
	ADDQ        $0x20, DX
	JMP         wide

wideDone:
	VPSUBUSB wire<>+544(SB), Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      invalid
	MOVQ     DI, AX
	SUBQ     (SP), AX
	SHRQ     $0x01, AX
	NOTQ     AX
	JMP      done

invalid:
	MOVQ $0x7fffffffffffffff, AX

done:
	MOVQ  16(SP), DI
	MOVQ  $0x7fffffffffffffff, CX
	CMPQ  AX, CX
	JEQ   finish
	TESTQ AX, AX
	JS    store16

	// Latin-1: the header 2n+1.
	LEAL 1(AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

store16:
	// UTF-16: the header 2n.
	NOTQ AX
	LEAL (AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*2), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

finish:
	MOVQ R14, done+40(FP)
	MOVQ 16(SP), AX
	SUBQ dst+0(FP), AX
	MOVQ AX, written+48(FP)
	VZEROUPPER
	RET

// func utf16UTF8AVX512(dst unsafe.Pointer, src unsafe.Pointer, units int) int
// Requires: AVX, AVX512BW, AVX512F, AVX512VBMI, AVX512VBMI2, AVX512VL, POPCNT
TEXT ·utf16UTF8AVX512(SB), NOSPLIT, $0-32
	MOVQ         dst+0(FP), AX
	MOVQ         src+8(FP), DX
	MOVQ         units+16(FP), BX
	MOVQ         AX, SI
	MOVL         $0x0000fc00, CX
	VPBROADCASTD CX, Z0
	MOVL         $0x0000d800, CX
	VPBROADCASTD CX, Z1
	MOVL         $0x0000dc00, CX
	VPBROADCASTD CX, Z2
	MOVL         $0x00000080, CX
	VPBROADCASTD CX, Z3
	MOVL         $0x00000800, CX
	VPBROADCASTD CX, Z4
	MOVL         $0xfca02400, CX
	VPBROADCASTD CX, Z5
	MOVQ         $0x20262c3200060c12, CX
	VPBROADCASTQ CX, Z6
	MOVL         $0x3f3f3f07, CX
	VPBROADCASTD CX, Z7
	MOVL         $0x808080f0, CX
	VPBROADCASTD CX, Z8
	MOVL         $0x00000018, CX
	VPBROADCASTD CX, Z9
	MOVL         $0x00000008, CX
	VPBROADCASTD CX, Z10
	MOVL         $0x00000020, CX
	VPBROADCASTD CX, Z11
	MOVL         $0x00000040, CX
	VPBROADCASTD CX, Z12
	MOVL         $0x00000020, CX
	VPBROADCASTD CX, Z13
	VPTERNLOGD   $0xff, Z14, Z14, Z14
	XORQ         DI, DI

next:
	MOVQ BX, CX
	SUBQ DI, CX
	JLE  finish
	MOVL $0x0000ffff, R8
	CMPQ CX, $0x10
	JAE  full
	MOVL $0x00000001, R8
	SHLL CL, R8
	DECL R8

full:
	MOVL R8, R9
	SHRL $0x01, R9
	CMPQ CX, $0x11
	JB   after
	MOVL $0x0000ffff, R9

after:
	MOVL  R8, CX
	TESTQ DI, DI
	JNZ   before
	ANDL  $0x0000fffe, CX

before:
	KMOVW          R8, K1
	KMOVW          R9, K2
	KMOVW          CX, K3
	VMOVDQU16.Z    (DX)(DI*2), K1, Y15
	VMOVDQU16.Z    2(DX)(DI*2), K2, Y16
	VMOVDQU16.Z    -2(DX)(DI*2), K3, Y17
	VPMOVZXWD      Y15, Z15
	VPMOVZXWD      Y16, Z16
	VPMOVZXWD      Y17, Z17
	VPANDD         Z0, Z15, Z18
	VPCMPEQD       Z1, Z18, K2
	VPCMPEQD       Z2, Z18, K3
	VPANDD         Z0, Z16, Z18
	VPCMPEQD       Z2, Z18, K4
	VPANDD         Z0, Z17, Z18
	VPCMPEQD       Z1, Z18, K5
	KANDW          K4, K2, K2
	KANDW          K5, K3, K3
	VPSLLD         $0x0a, Z15, Z18
	VPADDD         Z16, Z18, Z18
	VPADDD         Z5, Z18, Z18
	VMOVDQA32      Z18, K2, Z15
	VPMULTISHIFTQB Z15, Z6, Z16
	VPTERNLOGD     $0xea, Z8, Z7, Z16
	VPCMPUD        $0x05, Z3, Z15, K4
	VPCMPUD        $0x05, Z4, Z15, K5
	VMOVDQA32      Z9, Z17
	VPSUBD         Z10, Z17, K4, Z17
	VPSUBD         Z10, Z17, K5, Z17
	VPSUBD         Z10, Z17, K2, Z17
	VMOVDQA32      Z11, K3, Z17
	VPSRLVD        Z17, Z16, Z16
	VPORD          Z12, Z16, K4, Z16
	VPORD          Z13, Z16, K5, Z16
	KNOTW          K4, K2
	VMOVDQA32      Z15, K2, Z16
	VPSRLVD        Z17, Z14, Z15
	VMOVDQA32.Z    Z15, K1, Z15
	VPTESTMB       Z15, Z15, K1
	VPCOMPRESSB    Z16, K1, Z16
	VMOVDQU64      Z16, (AX)
	KMOVQ          K1, CX
	POPCNTQ        CX, CX
	ADDQ           CX, AX
	ADDQ           $0x10, DI
	JMP            next

finish:
	SUBQ SI, AX
	MOVQ AX, ret+24(FP)
	VZEROUPPER
	RET

// func latin1UTF8AVX512(dst unsafe.Pointer, src unsafe.Pointer, n int) int
// Requires: AVX, AVX512BW, AVX512F, AVX512VBMI2, AVX512VL, POPCNT
TEXT ·latin1UTF8AVX512(SB), NOSPLIT, $0-32
	MOVQ         dst+0(FP), AX
	MOVQ         src+8(FP), DX
	MOVQ         n+16(FP), BX
	MOVQ         AX, SI
	MOVL         $0x00003f00, CX
	VPBROADCASTW CX, Z0
	MOVL         $0x000080c0, CX
	VPBROADCASTW CX, Z1
	MOVQ         $0x5555555555555555, DI
	XORQ         R8, R8

next:
	MOVQ BX, CX
	SUBQ R8, CX
	JLE  finish
	MOVL $0xffffffff, R9
	MOVQ DI, R10
	CMPQ CX, $0x20
	JAE  full
	MOVL $0x00000001, R9
	SHLL CL, R9
	DECL R9
	ADDQ CX, CX
	MOVQ $0x00000001, R11
	SHLQ CL, R11
	DECQ R11
	ANDQ R11, R10

full:
	KMOVD       R9, K1
	VMOVDQU8.Z  (DX)(R8*1), K1, Y2
	VPMOVB2M    Y2, K1
	VPMOVZXBW   Y2, Z2
	VPSRLW      $0x06, Z2, Z3
	VPSLLW      $0x08, Z2, Z4
	VPANDD      Z0, Z4, Z4
	VPTERNLOGD  $0xfe, Z1, Z4, Z3
	VMOVDQU16   Z3, K1, Z2
	VPMOVB2M    Z2, K1
	KMOVQ       K1, CX
	ORQ         R10, CX
	KMOVQ       CX, K1
	VPCOMPRESSB Z2, K1, Z2
	VMOVDQU64   Z2, (AX)
	POPCNTQ     CX, CX
	ADDQ        CX, AX
	ADDQ        $0x20, R8
	JMP         next

finish:
	SUBQ SI, AX
	MOVQ AX, ret+24(FP)
	VZEROUPPER
	RET

// func latin1UTF8SSE(dst unsafe.Pointer, src unsafe.Pointer, n int) int
// Requires: SSE2, SSSE3
TEXT ·latin1UTF8SSE(SB), NOSPLIT, $0-32
	MOVQ  dst+0(FP), DI
	MOVQ  src+8(FP), SI
	MOVQ  n+16(FP), BX
	MOVQ  DI, R11
	XORQ  DX, DX
	LEAQ  ·pairShuf+0(SB), R8
	LEAQ  ·pairLen+0(SB), R9
	MOVOU wire<>+448(SB), X13
	MOVOU wire<>+0(SB), X14
	MOVOU wire<>+192(SB), X15

loop:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   finish
	LEAQ  (SI)(DX*1), R10
	CMPQ  CX, $0x10
	JB    tail
	MOVOU (R10), X0

body:
	PMOVMSKB X0, AX
	TESTL    AX, AX
	JNZ      high
	MOVOU    X0, (DI)
	ADDQ     $0x10, DI
	ADDQ     $0x10, DX
	JMP      loop

high:
	MOVOA     X0, X1
	PSRLW     $0x06, X1
	PAND      X13, X1
	POR       X14, X1
	PXOR      X2, X2
	PCMPGTB   X0, X2
	PAND      X15, X2
	PANDN     X0, X2
	MOVOA     X1, X3
	PUNPCKLBW X2, X3
	PUNPCKHBW X2, X1
	MOVL      AX, CX
	ANDL      $0x000000ff, CX
	SHRL      $0x08, AX
	MOVQ      CX, R12
	SHLQ      $0x04, R12
	MOVOU     (R8)(R12*1), X4
	PSHUFB    X4, X3
	MOVQ      AX, R12
	SHLQ      $0x04, R12
	MOVOU     (R8)(R12*1), X5
	PSHUFB    X5, X1
	MOVBLZX   (R9)(CX*1), R12
	MOVBLZX   (R9)(AX*1), R13
	MOVOU     X3, (DI)
	ADDQ      R12, DI
	MOVOU     X1, (DI)
	ADDQ      R13, DI
	ADDQ      $0x10, DX
	JMP       loop

tail:
	MOVQ  CX, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    cross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   body

cross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

byte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      byte
	MOVOU   (DI), X0
	JMP     body

finish:
	SUBQ BX, DX
	SUBQ DX, DI
	SUBQ R11, DI
	MOVQ DI, ret+24(FP)
	RET

// func utf16UTF8SSE(dst unsafe.Pointer, src unsafe.Pointer, units int) int
// Requires: SSE2, SSSE3
TEXT ·utf16UTF8SSE(SB), NOSPLIT, $0-32
	MOVQ  dst+0(FP), DI
	MOVQ  src+8(FP), SI
	MOVQ  units+16(FP), BX
	MOVQ  DI, R11
	XORQ  DX, DX
	PXOR  X7, X7
	MOVOU wire<>+768(SB), X8
	MOVOU wire<>+800(SB), X9
	MOVOU wire<>+896(SB), X10
	MOVOU wire<>+928(SB), X11
	MOVOU wire<>+960(SB), X12
	MOVOU wire<>+992(SB), X13
	MOVOU wire<>+1024(SB), X14
	MOVOU wire<>+832(SB), X15

loop:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   finish
	LEAQ  (SI)(DX*2), R10
	CMPQ  CX, $0x08
	JB    tail
	MOVOU (R10), X0

body:
	MOVOA    X0, X1
	PAND     X8, X1
	PCMPEQW  X7, X1
	PMOVMSKB X1, AX
	CMPL     AX, $0x0000ffff
	JNE      wide
	PACKUSWB X0, X0
	MOVQ     X0, (DI)
	ADDQ     $0x08, DI
	ADDQ     $0x08, DX
	JMP      loop

wide:
	MOVOA    X0, X3
	PAND     X9, X3
	PCMPEQW  X7, X3
	PMOVMSKB X3, CX
	MOVOA    X1, X6
	PACKSSWB X6, X6
	PMOVMSKB X6, R13
	NOTL     R13
	ANDL     $0x000000ff, R13

	// The last byte of each: the unit for ASCII, else 80 | u & 3F.
	MOVOA X0, X4
	PAND  X10, X4
	POR   X11, X4
	MOVOA X1, X5
	PAND  X0, X5
	PANDN X4, X1
	POR   X5, X1
	CMPL  CX, $0x0000ffff
	JNE   three

	// Each below 800: its lead C0 | u >> 6 and the last byte, as a pair.
	MOVOA   X0, X2
	PSRLW   $0x06, X2
	POR     X12, X2
	PSLLW   $0x08, X1
	POR     X1, X2
	MOVQ    R13, R12
	SHLQ    $0x04, R12
	LEAQ    ·pairShuf+0(SB), R14
	MOVOU   (R14)(R12*1), X4
	PSHUFB  X4, X2
	MOVOU   X2, (DI)
	LEAQ    ·pairLen+0(SB), R14
	MOVBLZX (R14)(R13*1), R12
	ADDQ    R12, DI
	ADDQ    $0x08, DX
	JMP     loop

three:
	// Each as 4 bytes: E0 | u >> 12, 80 | (u >> 6) & 3F (C0 | u >> 6 below 800), the last byte, 0.
	MOVOA     X0, X2
	PSRLW     $0x0c, X2
	POR       X13, X2
	MOVOA     X0, X4
	PSRLW     $0x06, X4
	PAND      X10, X4
	POR       X11, X4
	PAND      X14, X3
	POR       X3, X4
	PSLLW     $0x08, X4
	POR       X4, X2
	MOVOA     X2, X4
	PUNPCKLWL X1, X2
	PUNPCKHWL X1, X4

	// Two bits a unit: 0 for 1 byte, 1 for 2, 3 for 3 (2: none).
	NOTL AX
	ANDL $0x00005555, AX
	NOTL CX
	ANDL $0x0000aaaa, CX
	ORL  CX, AX

	// High surrogates.
	MOVOU    wire<>+864(SB), X6
	MOVOA    X0, X5
	PAND     X15, X5
	PCMPEQW  X6, X5
	PMOVMSKB X5, R13
	MOVQ     $0x00000008, R14
	TESTL    R13, R13
	JNZ      cut

emit:
	MOVL    AX, CX
	ANDL    $0x000000ff, CX
	SHRL    $0x08, AX
	LEAQ    ·u3Shuf+0(SB), R8
	MOVQ    CX, R12
	SHLQ    $0x04, R12
	MOVOU   (R8)(R12*1), X5
	PSHUFB  X5, X2
	MOVQ    AX, R12
	SHLQ    $0x04, R12
	MOVOU   (R8)(R12*1), X6
	PSHUFB  X6, X4
	LEAQ    ·u3Len+0(SB), R8
	MOVBLZX (R8)(CX*1), R12
	MOVBLZX (R8)(AX*1), R13
	MOVOU   X2, (DI)
	ADDQ    R12, DI
	MOVOU   X4, (DI)
	ADDQ    R13, DI
	ADDQ    R14, DX
	CMPQ    R14, $0x08
	JNE     surrogate
	JMP     loop

cut:
	// The units before the first high surrogate (k of them) only.
	BSFL R13, CX
	MOVL CX, R14
	SHRL $0x01, R14
	MOVL $0x00000001, R12
	SHLL CL, R12
	DECL R12
	ANDL R12, AX
	NOTL R12
	ANDL $0x0000aaaa, R12
	ORL  R12, AX
	JMP  emit

surrogate:
	// A high surrogate at DX: with the low one after it, 4 bytes; else alone, 3.
	MOVWLZX (SI)(DX*2), AX
	LEAQ    1(DX), R12
	CMPQ    R12, BX
	JAE     lone
	MOVWLZX 2(SI)(DX*2), CX
	MOVL    CX, R12
	ANDL    $0x0000fc00, R12
	CMPL    R12, $0x0000dc00
	JNE     lone
	SHLL    $0x0a, AX
	ADDL    CX, AX
	SUBL    $0x035fdc00, AX
	MOVL    AX, CX
	SHRL    $0x12, CX
	ORL     $0x000000f0, CX
	MOVL    AX, R12
	SHRL    $0x0c, R12
	ANDL    $0x3f, R12
	ORL     $0x00000080, R12
	SHLL    $0x08, R12
	ORL     R12, CX
	MOVL    AX, R12
	SHRL    $0x06, R12
	ANDL    $0x3f, R12
	ORL     $0x00000080, R12
	SHLL    $0x10, R12
	ORL     R12, CX
	ANDL    $0x3f, AX
	ORL     $0x00000080, AX
	SHLL    $0x18, AX
	ORL     AX, CX
	MOVL    CX, (DI)
	ADDQ    $0x04, DI
	ADDQ    $0x02, DX
	JMP     loop

lone:
	MOVL AX, CX
	SHRL $0x0c, CX
	ORL  $0x000000e0, CX
	MOVL AX, R12
	SHRL $0x06, R12
	ANDL $0x3f, R12
	ORL  $0x00000080, R12
	SHLL $0x08, R12
	ORL  R12, CX
	ANDL $0x3f, AX
	ORL  $0x00000080, AX
	SHLL $0x10, AX
	ORL  AX, CX
	MOVL CX, (DI)
	ADDQ $0x03, DI
	INCQ DX
	JMP  loop

tail:
	MOVQ  CX, R12
	SHLQ  $0x01, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    cross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   body

cross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

byte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      byte
	MOVOU   (DI), X0
	JMP     body

finish:
	SUBQ BX, DX
	SUBQ DX, DI
	SUBQ R11, DI
	MOVQ DI, ret+24(FP)
	RET

// func wireStringSSE(dst unsafe.Pointer, i int, src unsafe.Pointer, n int) int
// Requires: SSE2, SSSE3
TEXT ·wireStringSSE(SB), NOSPLIT, $16-40
	MOVQ  src+16(FP), SI
	MOVQ  i+8(FP), DX
	ADDQ  DX, SI
	MOVQ  n+24(FP), BX
	SUBQ  DX, BX
	MOVQ  dst+0(FP), DI
	LEAQ  (DI)(DX*2), AX
	MOVQ  AX, (SP)
	ADDQ  DX, DI
	MOVQ  DI, 8(SP)
	PXOR  X13, X13
	MOVOU wire<>+32(SB), X14
	MOVOU wire<>+0(SB), X15
	XORQ  DX, DX
	PXOR  X11, X11
	PXOR  X12, X12

latin1:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   latin1Done
	LEAQ  (SI)(DX*1), R10
	CMPQ  CX, $0x10
	JB    ltail
	MOVOU (R10), X0

lbody:
	PMOVMSKB X0, AX
	TESTL    AX, AX
	JNZ      lchars

	// ASCII: no char of the block before may be cut.
	MOVOU   wire<>+560(SB), X4
	MOVOA   X11, X5
	PSUBUSB X4, X5
	POR     X5, X12
	MOVOU   X0, (DI)
	ADDQ    $0x10, DI
	MOVOA   X0, X11
	ADDQ    $0x10, DX
	JMP     latin1

lchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	MOVOA    X0, X4
	MOVOU    wire<>+160(SB), X5
	PSUBUSB  X5, X4
	PCMPEQB  X13, X4
	PMOVMSKB X4, R8
	CMPL     R8, $0x0000ffff
	JNE      toUTF16

	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly
	// the bytes after the leads, and there are no C0 or C1.
	MOVOA      X0, X2
	PALIGNR    $0x0f, X11, X2
	MOVOU      wire<>+224(SB), X6
	MOVOU      wire<>+256(SB), X7
	MOVOA      X0, X4
	PAND       X6, X4
	MOVOA      X4, X5
	PCMPEQB    X7, X4
	PCMPEQB    X15, X5
	POR        X5, X12
	MOVOA      X2, X5
	PAND       X6, X5
	PCMPEQB    X7, X5
	MOVOA      X15, X6
	PCMPGTB    X0, X6
	PXOR       X6, X5
	POR        X5, X12
	MOVOU      wire<>+160(SB), X5
	PCMPEQB    X2, X5
	MOVOU      wire<>+192(SB), X6
	PAND       X6, X5
	PADDB      X0, X5
	MOVOA      X0, X11
	PMOVMSKB   X4, R8
	NOTL       R8
	MOVL       R8, R9
	ANDL       $0x000000ff, R9
	SHRL       $0x08, R8
	ANDL       $0x000000ff, R8
	LEAQ       ·narrowLo+0(SB), AX
	MOVQ       (AX)(R9*8), X6
	LEAQ       ·narrowHi+0(SB), AX
	MOVQ       (AX)(R8*8), X7
	PUNPCKLQDQ X7, X6
	PSHUFB     X6, X5
	LEAQ       ·pairLen+0(SB), AX
	MOVBLZX    (AX)(R9*1), R10
	MOVBLZX    (AX)(R8*1), R11
	MOVQ       X5, (DI)
	LEAQ       -8(DI)(R10*1), DI
	PSRLDQ     $0x08, X5
	MOVQ       X5, (DI)
	LEAQ       -8(DI)(R11*1), DI
	ADDQ       $0x10, DX
	JMP        latin1

ltail:
	MOVQ  CX, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    lcross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   lbody

lcross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

lbyte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      lbyte
	MOVOU   (DI), X0
	JMP     lbody

latin1Done:
	MOVOU    wire<>+560(SB), X4
	MOVOA    X11, X5
	PSUBUSB  X4, X5
	POR      X5, X12
	PCMPEQB  X13, X12
	PMOVMSKB X12, R8
	CMPL     R8, $0x0000ffff
	JNE      invalid
	MOVQ     DI, AX
	SUBQ     8(SP), AX
	MOVQ     DX, CX
	SUBQ     BX, CX
	SUBQ     CX, AX
	JMP      done

toUTF16:
	// From the start again, as UTF-16: the block in X0 when it is the first.
	MOVQ  (SP), DI
	PXOR  X11, X11
	PXOR  X12, X12
	TESTQ DX, DX
	JZ    wchars
	XORQ  DX, DX

wide:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   wideDone
	LEAQ  (SI)(DX*1), R10
	CMPQ  CX, $0x10
	JB    wtail
	MOVOU (R10), X0

wbody:
	PMOVMSKB  X0, AX
	TESTL     AX, AX
	JNZ       wchars
	MOVOU     wire<>+560(SB), X4
	MOVOA     X11, X5
	PSUBUSB   X4, X5
	POR       X5, X12
	MOVOA     X0, X4
	PUNPCKLBW X13, X4
	MOVOA     X0, X5
	PUNPCKHBW X13, X5
	MOVOU     X4, (DI)
	MOVOU     X5, 16(DI)
	ADDQ      $0x20, DI
	MOVOA     X0, X11
	ADDQ      $0x10, DX
	JMP       wide

wchars:
	// Check the block (Keiser and Lemire): X2 the byte one before each, X3 two before, X1 three before.
	MOVOA    X0, X2
	PALIGNR  $0x0f, X11, X2
	MOVOA    X0, X3
	PALIGNR  $0x0e, X11, X3
	MOVOA    X0, X1
	PALIGNR  $0x0d, X11, X1
	MOVOA    X2, X4
	PSRLW    $0x04, X4
	PAND     X14, X4
	MOVOU    wire<>+576(SB), X7
	PSHUFB   X4, X7
	MOVOA    X2, X5
	PAND     X14, X5
	MOVOU    wire<>+608(SB), X8
	PSHUFB   X5, X8
	MOVOA    X0, X6
	PSRLW    $0x04, X6
	PAND     X14, X6
	MOVOU    wire<>+640(SB), X9
	PSHUFB   X6, X9
	PAND     X8, X7
	PAND     X9, X7
	MOVOA    X3, X5
	MOVOU    wire<>+64(SB), X8
	PSUBUSB  X8, X5
	MOVOA    X1, X6
	MOVOU    wire<>+96(SB), X8
	PSUBUSB  X8, X6
	POR      X6, X5
	MOVOU    wire<>+128(SB), X8
	PAND     X8, X5
	PXOR     X5, X7
	POR      X7, X12
	MOVOA    X0, X11
	MOVOA    X15, X4
	PCMPGTB  X0, X4
	MOVOA    X15, X5
	PCMPGTB  X2, X5
	MOVOU    wire<>+288(SB), X6
	PAND     X2, X6
	PCMPEQB  X15, X6
	PXOR     X7, X7
	PCMPGTB  X0, X7
	POR      X6, X5
	PAND     X4, X5
	PANDN    X7, X5
	PMOVMSKB X5, R8
	NOTL     R8

	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	MOVOU wire<>+384(SB), X4
	PAND  X0, X4
	MOVOA X2, X5
	PSLLW $0x06, X5
	PAND  X15, X5
	POR   X5, X4
	PAND  X7, X4
	MOVOA X7, X5
	PANDN X0, X5
	POR   X5, X4

	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	MOVOA X2, X9
	PSRLW $0x02, X9
	PAND  X14, X9
	MOVOA X3, X8
	PSLLW $0x04, X8
	MOVOU wire<>+320(SB), X5
	PAND  X5, X8
	POR   X9, X8
	MOVOA X6, X5
	PAND  X9, X5
	PANDN X8, X6
	POR   X5, X6
	PAND  X7, X6

	// Surrogates: b2 the lead of 4 bytes (the high one, X10), or b3 (the low one, X7).
	MOVOU    wire<>+352(SB), X5
	MOVOU    wire<>+320(SB), X8
	MOVOA    X3, X10
	PAND     X5, X10
	PCMPEQB  X8, X10
	MOVOA    X1, X7
	PAND     X5, X7
	PCMPEQB  X8, X7
	MOVOA    X10, X5
	POR      X7, X5
	PMOVMSKB X5, AX
	TESTL    AX, AX
	JZ       wpack

	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	MOVOU   wire<>+384(SB), X5
	PAND    X2, X5
	PSLLW   $0x02, X5
	MOVOA   X0, X8
	PSRLW   $0x04, X8
	MOVOU   wire<>+448(SB), X1
	PAND    X1, X8
	POR     X8, X5
	MOVOU   wire<>+192(SB), X8
	MOVOA   X5, X9
	PSUBB   X8, X9
	PAND    X10, X9
	MOVOA   X10, X8
	PANDN   X4, X8
	POR     X9, X8
	MOVOA   X8, X4
	PAND    X15, X5
	PCMPEQB X13, X5
	MOVOU   wire<>+416(SB), X8
	PAND    X3, X8
	MOVOU   wire<>+480(SB), X9
	PADDB   X9, X8
	PADDB   X5, X8
	PAND    X10, X8
	PANDN   X6, X10
	POR     X8, X10
	MOVOA   X10, X6

	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	MOVOA X2, X8
	PSRLW $0x02, X8
	MOVOU wire<>+448(SB), X9
	PAND  X9, X8
	MOVOU wire<>+512(SB), X9
	POR   X9, X8
	PAND  X7, X8
	PANDN X6, X7
	POR   X8, X7
	MOVOA X7, X6

wpack:
	MOVOA     X4, X5
	PUNPCKLBW X6, X5
	PUNPCKHBW X6, X4
	MOVL      R8, R9
	ANDL      $0x000000ff, R9
	SHRL      $0x08, R8
	ANDL      $0x000000ff, R8
	LEAQ      ·wideShuf+0(SB), AX
	MOVQ      R9, R10
	SHLQ      $0x04, R10
	MOVOU     (AX)(R10*1), X7
	PSHUFB    X7, X5
	MOVQ      R8, R10
	SHLQ      $0x04, R10
	MOVOU     (AX)(R10*1), X7
	PSHUFB    X7, X4
	LEAQ      ·pairLen+0(SB), AX
	MOVBLZX   (AX)(R9*1), R10
	MOVBLZX   (AX)(R8*1), R11
	MOVOU     X5, (DI)
	LEAQ      -16(DI)(R10*2), DI
	MOVOU     X4, (DI)
	LEAQ      -16(DI)(R11*2), DI
	ADDQ      $0x10, DX
	JMP       wide

wtail:
	MOVQ  CX, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    wcross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   wbody

wcross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

wbyte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      wbyte
	MOVOU   (DI), X0
	JMP     wbody

wideDone:
	MOVOU    wire<>+560(SB), X4
	MOVOA    X11, X5
	PSUBUSB  X4, X5
	POR      X5, X12
	PCMPEQB  X13, X12
	PMOVMSKB X12, R8
	CMPL     R8, $0x0000ffff
	JNE      invalid
	MOVQ     DI, AX
	SUBQ     (SP), AX
	SHRQ     $0x01, AX
	MOVQ     DX, CX
	SUBQ     BX, CX
	SUBQ     CX, AX
	NOTQ     AX
	JMP      done

invalid:
	MOVQ $0x7fffffffffffffff, AX

done:
	MOVQ AX, ret+32(FP)
	RET

// func wireStringsSSE(dst unsafe.Pointer, room int, strs unsafe.Pointer, count int, ptrs bool) (done int, written int)
// Requires: SSE2, SSSE3
TEXT ·wireStringsSSE(SB), NOSPLIT, $32-56
	MOVQ  dst+0(FP), AX
	MOVQ  AX, 16(SP)
	ADDQ  room+8(FP), AX
	MOVQ  AX, 24(SP)
	XORQ  R14, R14
	PXOR  X13, X13
	MOVOU wire<>+32(SB), X14
	MOVOU wire<>+0(SB), X15

next:
	MOVQ  R14, CX
	CMPQ  CX, count+24(FP)
	JAE   finish
	MOVQ  strs+16(FP), R8
	CMPB  ptrs+32(FP), $0x00
	JEQ   value
	MOVQ  (R8)(CX*8), R8
	TESTQ R8, R8
	JNZ   header

	// nil: the null string.
	MOVQ 16(SP), DI
	LEAQ 1(DI), AX
	CMPQ AX, 24(SP)
	JA   finish
	MOVB $0x00, (DI)
	MOVQ AX, 16(SP)
	INCQ R14
	JMP  next

value:
	SHLQ $0x04, CX
	ADDQ CX, R8

header:
	MOVQ  (R8), SI
	MOVQ  8(R8), BX
	MOVQ  16(SP), DI
	TESTQ BX, BX
	JNZ   text
	LEAQ  1(DI), AX
	CMPQ  AX, 24(SP)
	JA    finish
	MOVB  $0x01, (DI)
	MOVQ  AX, 16(SP)
	INCQ  R14
	JMP   next

text:
	CMPQ     BX, $const_wireMaxText
	JAE      finish
	LEAQ     const_wireSlack+1(DI)(BX*2), AX
	CMPQ     AX, 24(SP)
	JA       finish
	CMPQ     BX, $0x10
	JAE      long
	LEAQ     -1(SI), R8
	MOVL     R8, R9
	ANDL     $0x00000fff, R9
	CMPL     R9, $0x00000ff0
	JA       long
	LEAQ     wire<>+672(SB), R10
	ADDQ     $0x1f, R10
	SUBQ     BX, R10
	MOVOU    (R8), X0
	MOVOU    (R10), X1
	PAND     X1, X0
	MOVOU    wire<>+736(SB), X1
	PAND     X1, X0
	PMOVMSKB X0, R8
	TESTL    R8, R8
	JNZ      long

	// The header, 2n+1, in the first byte.
	LEAL  1(BX)(BX*1), CX
	MOVD  CX, X1
	POR   X1, X0
	MOVOU X0, (DI)

	// Stored with its header.
	LEAQ 1(DI)(BX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

long:
	INCQ DI
	MOVQ DI, 8(SP)
	MOVQ DI, (SP)
	XORQ DX, DX
	PXOR X11, X11
	PXOR X12, X12

latin1:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   latin1Done
	LEAQ  (SI)(DX*1), R10
	CMPQ  CX, $0x10
	JB    ltail
	MOVOU (R10), X0

lbody:
	PMOVMSKB X0, AX
	TESTL    AX, AX
	JNZ      lchars

	// ASCII: no char of the block before may be cut.
	MOVOU   wire<>+560(SB), X4
	MOVOA   X11, X5
	PSUBUSB X4, X5
	POR     X5, X12
	MOVOU   X0, (DI)
	ADDQ    $0x10, DI
	MOVOA   X0, X11
	ADDQ    $0x10, DX
	JMP     latin1

lchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	MOVOA    X0, X4
	MOVOU    wire<>+160(SB), X5
	PSUBUSB  X5, X4
	PCMPEQB  X13, X4
	PMOVMSKB X4, R8
	CMPL     R8, $0x0000ffff
	JNE      toUTF16

	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly
	// the bytes after the leads, and there are no C0 or C1.
	MOVOA      X0, X2
	PALIGNR    $0x0f, X11, X2
	MOVOU      wire<>+224(SB), X6
	MOVOU      wire<>+256(SB), X7
	MOVOA      X0, X4
	PAND       X6, X4
	MOVOA      X4, X5
	PCMPEQB    X7, X4
	PCMPEQB    X15, X5
	POR        X5, X12
	MOVOA      X2, X5
	PAND       X6, X5
	PCMPEQB    X7, X5
	MOVOA      X15, X6
	PCMPGTB    X0, X6
	PXOR       X6, X5
	POR        X5, X12
	MOVOU      wire<>+160(SB), X5
	PCMPEQB    X2, X5
	MOVOU      wire<>+192(SB), X6
	PAND       X6, X5
	PADDB      X0, X5
	MOVOA      X0, X11
	PMOVMSKB   X4, R8
	NOTL       R8
	MOVL       R8, R9
	ANDL       $0x000000ff, R9
	SHRL       $0x08, R8
	ANDL       $0x000000ff, R8
	LEAQ       ·narrowLo+0(SB), AX
	MOVQ       (AX)(R9*8), X6
	LEAQ       ·narrowHi+0(SB), AX
	MOVQ       (AX)(R8*8), X7
	PUNPCKLQDQ X7, X6
	PSHUFB     X6, X5
	LEAQ       ·pairLen+0(SB), AX
	MOVBLZX    (AX)(R9*1), R10
	MOVBLZX    (AX)(R8*1), R11
	MOVQ       X5, (DI)
	LEAQ       -8(DI)(R10*1), DI
	PSRLDQ     $0x08, X5
	MOVQ       X5, (DI)
	LEAQ       -8(DI)(R11*1), DI
	ADDQ       $0x10, DX
	JMP        latin1

ltail:
	MOVQ  CX, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    lcross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   lbody

lcross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

lbyte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      lbyte
	MOVOU   (DI), X0
	JMP     lbody

latin1Done:
	MOVOU    wire<>+560(SB), X4
	MOVOA    X11, X5
	PSUBUSB  X4, X5
	POR      X5, X12
	PCMPEQB  X13, X12
	PMOVMSKB X12, R8
	CMPL     R8, $0x0000ffff
	JNE      invalid
	MOVQ     DI, AX
	SUBQ     8(SP), AX
	MOVQ     DX, CX
	SUBQ     BX, CX
	SUBQ     CX, AX
	JMP      done

toUTF16:
	// From the start again, as UTF-16: the block in X0 when it is the first.
	MOVQ  (SP), DI
	PXOR  X11, X11
	PXOR  X12, X12
	TESTQ DX, DX
	JZ    wchars
	XORQ  DX, DX

wide:
	MOVQ  BX, CX
	SUBQ  DX, CX
	JLE   wideDone
	LEAQ  (SI)(DX*1), R10
	CMPQ  CX, $0x10
	JB    wtail
	MOVOU (R10), X0

wbody:
	PMOVMSKB  X0, AX
	TESTL     AX, AX
	JNZ       wchars
	MOVOU     wire<>+560(SB), X4
	MOVOA     X11, X5
	PSUBUSB   X4, X5
	POR       X5, X12
	MOVOA     X0, X4
	PUNPCKLBW X13, X4
	MOVOA     X0, X5
	PUNPCKHBW X13, X5
	MOVOU     X4, (DI)
	MOVOU     X5, 16(DI)
	ADDQ      $0x20, DI
	MOVOA     X0, X11
	ADDQ      $0x10, DX
	JMP       wide

wchars:
	// Check the block (Keiser and Lemire): X2 the byte one before each, X3 two before, X1 three before.
	MOVOA    X0, X2
	PALIGNR  $0x0f, X11, X2
	MOVOA    X0, X3
	PALIGNR  $0x0e, X11, X3
	MOVOA    X0, X1
	PALIGNR  $0x0d, X11, X1
	MOVOA    X2, X4
	PSRLW    $0x04, X4
	PAND     X14, X4
	MOVOU    wire<>+576(SB), X7
	PSHUFB   X4, X7
	MOVOA    X2, X5
	PAND     X14, X5
	MOVOU    wire<>+608(SB), X8
	PSHUFB   X5, X8
	MOVOA    X0, X6
	PSRLW    $0x04, X6
	PAND     X14, X6
	MOVOU    wire<>+640(SB), X9
	PSHUFB   X6, X9
	PAND     X8, X7
	PAND     X9, X7
	MOVOA    X3, X5
	MOVOU    wire<>+64(SB), X8
	PSUBUSB  X8, X5
	MOVOA    X1, X6
	MOVOU    wire<>+96(SB), X8
	PSUBUSB  X8, X6
	POR      X6, X5
	MOVOU    wire<>+128(SB), X8
	PAND     X8, X5
	PXOR     X5, X7
	POR      X7, X12
	MOVOA    X0, X11
	MOVOA    X15, X4
	PCMPGTB  X0, X4
	MOVOA    X15, X5
	PCMPGTB  X2, X5
	MOVOU    wire<>+288(SB), X6
	PAND     X2, X6
	PCMPEQB  X15, X6
	PXOR     X7, X7
	PCMPGTB  X0, X7
	POR      X6, X5
	PAND     X4, X5
	PANDN    X7, X5
	PMOVMSKB X5, R8
	NOTL     R8

	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	MOVOU wire<>+384(SB), X4
	PAND  X0, X4
	MOVOA X2, X5
	PSLLW $0x06, X5
	PAND  X15, X5
	POR   X5, X4
	PAND  X7, X4
	MOVOA X7, X5
	PANDN X0, X5
	POR   X5, X4

	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	MOVOA X2, X9
	PSRLW $0x02, X9
	PAND  X14, X9
	MOVOA X3, X8
	PSLLW $0x04, X8
	MOVOU wire<>+320(SB), X5
	PAND  X5, X8
	POR   X9, X8
	MOVOA X6, X5
	PAND  X9, X5
	PANDN X8, X6
	POR   X5, X6
	PAND  X7, X6

	// Surrogates: b2 the lead of 4 bytes (the high one, X10), or b3 (the low one, X7).
	MOVOU    wire<>+352(SB), X5
	MOVOU    wire<>+320(SB), X8
	MOVOA    X3, X10
	PAND     X5, X10
	PCMPEQB  X8, X10
	MOVOA    X1, X7
	PAND     X5, X7
	PCMPEQB  X8, X7
	MOVOA    X10, X5
	POR      X7, X5
	PMOVMSKB X5, AX
	TESTL    AX, AX
	JZ       wpack

	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	MOVOU   wire<>+384(SB), X5
	PAND    X2, X5
	PSLLW   $0x02, X5
	MOVOA   X0, X8
	PSRLW   $0x04, X8
	MOVOU   wire<>+448(SB), X1
	PAND    X1, X8
	POR     X8, X5
	MOVOU   wire<>+192(SB), X8
	MOVOA   X5, X9
	PSUBB   X8, X9
	PAND    X10, X9
	MOVOA   X10, X8
	PANDN   X4, X8
	POR     X9, X8
	MOVOA   X8, X4
	PAND    X15, X5
	PCMPEQB X13, X5
	MOVOU   wire<>+416(SB), X8
	PAND    X3, X8
	MOVOU   wire<>+480(SB), X9
	PADDB   X9, X8
	PADDB   X5, X8
	PAND    X10, X8
	PANDN   X6, X10
	POR     X8, X10
	MOVOA   X10, X6

	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	MOVOA X2, X8
	PSRLW $0x02, X8
	MOVOU wire<>+448(SB), X9
	PAND  X9, X8
	MOVOU wire<>+512(SB), X9
	POR   X9, X8
	PAND  X7, X8
	PANDN X6, X7
	POR   X8, X7
	MOVOA X7, X6

wpack:
	MOVOA     X4, X5
	PUNPCKLBW X6, X5
	PUNPCKHBW X6, X4
	MOVL      R8, R9
	ANDL      $0x000000ff, R9
	SHRL      $0x08, R8
	ANDL      $0x000000ff, R8
	LEAQ      ·wideShuf+0(SB), AX
	MOVQ      R9, R10
	SHLQ      $0x04, R10
	MOVOU     (AX)(R10*1), X7
	PSHUFB    X7, X5
	MOVQ      R8, R10
	SHLQ      $0x04, R10
	MOVOU     (AX)(R10*1), X7
	PSHUFB    X7, X4
	LEAQ      ·pairLen+0(SB), AX
	MOVBLZX   (AX)(R9*1), R10
	MOVBLZX   (AX)(R8*1), R11
	MOVOU     X5, (DI)
	LEAQ      -16(DI)(R10*2), DI
	MOVOU     X4, (DI)
	LEAQ      -16(DI)(R11*2), DI
	ADDQ      $0x10, DX
	JMP       wide

wtail:
	MOVQ  CX, R12
	MOVL  R10, R13
	ANDL  $0x00000fff, R13
	CMPL  R13, $0x00000ff0
	JA    wcross
	MOVOU (R10), X0
	LEAQ  wire<>+672(SB), R13
	ADDQ  $0x20, R13
	SUBQ  R12, R13
	MOVOU (R13), X1
	PAND  X1, X0
	JMP   wbody

wcross:
	PXOR  X0, X0
	MOVOU X0, (DI)
	XORQ  R13, R13

wbyte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AL, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      wbyte
	MOVOU   (DI), X0
	JMP     wbody

wideDone:
	MOVOU    wire<>+560(SB), X4
	MOVOA    X11, X5
	PSUBUSB  X4, X5
	POR      X5, X12
	PCMPEQB  X13, X12
	PMOVMSKB X12, R8
	CMPL     R8, $0x0000ffff
	JNE      invalid
	MOVQ     DI, AX
	SUBQ     (SP), AX
	SHRQ     $0x01, AX
	MOVQ     DX, CX
	SUBQ     BX, CX
	SUBQ     CX, AX
	NOTQ     AX
	JMP      done

invalid:
	MOVQ $0x7fffffffffffffff, AX

done:
	MOVQ  16(SP), DI
	MOVQ  $0x7fffffffffffffff, CX
	CMPQ  AX, CX
	JEQ   finish
	TESTQ AX, AX
	JS    store16

	// Latin-1: the header 2n+1.
	LEAL 1(AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*1), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

store16:
	// UTF-16: the header 2n.
	NOTQ AX
	LEAL (AX)(AX*1), CX
	MOVB CL, (DI)
	LEAQ 1(DI)(AX*2), DI
	MOVQ DI, 16(SP)
	INCQ R14
	JMP  next

finish:
	MOVQ R14, done+40(FP)
	MOVQ 16(SP), AX
	SUBQ dst+0(FP), AX
	MOVQ AX, written+48(FP)
	RET

// func cpuid(eaxArg uint32, ecxArg uint32) (eax uint32, ebx uint32, ecx uint32, edx uint32)
// Requires: CPUID
TEXT ·cpuid(SB), NOSPLIT, $0-24
	MOVL eaxArg+0(FP), AX
	MOVL ecxArg+4(FP), CX
	CPUID
	MOVL AX, eax+8(FP)
	MOVL BX, ebx+12(FP)
	MOVL CX, ecx+16(FP)
	MOVL DX, edx+20(FP)
	RET

// func xgetbv() (eax uint32, edx uint32)
TEXT ·xgetbv(SB), NOSPLIT, $0-8
	MOVL $0x00000000, CX
	XGETBV
	MOVL AX, eax+0(FP)
	MOVL DX, edx+4(FP)
	RET
